[3094] = { en = "Verdant Note", tier = 1,
  t = "Verdant Note",
  d = "Net was er een boodschapper hier. Ze zocht jou, $N. Ik denk dat de druïdeleraar Gart haar heeft gestuurd. Is deze brief van Gart? Lees hem dan snel.$b",
  o = "Lees de Verdant Note en praat met Gart Mistrunner in Camp Narache.",
  p = "Je bent er. Dat is goed. De geesten van onze voorouders zijn onrustig, in heel Mulgore en verder. Maar ik weet niet waarom. Het is altijd jouw taak om te leren luisteren naar de geesten van de natuur. Jij spreekt en handelt voor hen. Denk daaraan.",
  c = "We hebben een band met de nachtelfen. Toch moet je van hen niet veel welkom verwachten. Door hun trots zien ze nog niet alles. Maar dat is niet ons probleem. Jij hoeft alleen te denken aan de lessen van de Earthmother. Ik leer je wat ik weet, als je wijzer wordt.$B$BKom vaak bij mij terug, $N. Je zult zien: de Earthmother geeft geweldige krachten aan wie het meest toegewijd is.",
  g = { {"boodschapper", "messenger"}, {"druïdeleraar", "druid trainer"}, {"voorouders", "ancestors (voorouder)"}, {"onrustig", "restless"}, {"geesten", "spirits (geest)"}, {"handelt", "acts (handelen)"}, {"band", "bond"}, {"nachtelfen", "night elves"}, {"trots", "pride"}, {"wijzer", "wiser (wijs)"}, {"toegewijd", "dedicated"}, {"krachten", "powers, abilities (kracht)"} },
},

[5922] = { en = "Moonglade", tier = 1,
  t = "Moonglade",
  d = "Alle druïden zijn welkom in de heilige landen van Moonglade, tauren en nachtelfen. Keeper Remulos is de beschermer van Moonglade. Hij waakt over alle druïden die daar in winterslaap zijn. Je leert nu de wegen van de Klauw. Daarom leer ik je de spreuk die je daarheen brengt. Gebruik hem als je de kennis of de troost van Moonglade zoekt.$B$BDan je eerste les: reis naar Moonglade. Praat daar met Dendrite Starblaze in Nighthaven over het pad dat je nu volgt. Veel succes, jonge druïde.",
  o = "Gebruik de spreuk \"Teleport: Moonglade\" om naar Moonglade te reizen. Praat daar met Dendrite Starblaze in het dorp Nighthaven.",
  c = "\"En zo begint het. Vader Cenarius. En zo begint het.\"$B$BDendrite maakt snel een onzichtbaar gebaar in de lucht boven zich. Een licht schijnsel van kracht valt over hem heen.$B$B\"Je moet je eerst aanpassen aan één blik op de natuur: die van de beer. Ik zet je op het pad om dit deel van het druïdeleven te begrijpen. Maar jij moet het omarmen en verspreiden. Nu en voor altijd!\"",
  g = { {"heilige", "holy, sacred (heilig)"}, {"beschermer", "protector, guardian"}, {"waakt", "keeps watch (waken)"}, {"winterslaap", "hibernation"}, {"Klauw", "Claw"}, {"spreuk", "spell"}, {"troost", "comfort, solace"}, {"onzichtbaar", "invisible"}, {"gebaar", "gesture"}, {"schijnsel", "glow, aura"}, {"aanpassen", "to adapt"}, {"omarmen", "to embrace"}, {"verspreiden", "to spread"} },
},

[5926] = { en = "Heeding the Call", tier = 1,
  t = "De roep beantwoorden",
  d = "Pardon, vriend...$B$BIk heb gehoord dat Turak Runetotem met je wil praten. Hij heeft het laten weten. Het lijkt erop dat je training als druïde een nieuw leven krijgt. Hij gaat je zelf trainen. Turak is een van de helpers van de Arch Druid. Hij staat bekend als een wijze en geduldige druïde. Hij zal je goed lesgeven.$B$BJe vindt hem in Thunder Bluff, in de grote tent van de Cenarion Circle op de Elder Rise.",
  o = "Praat met Turak Runetotem op de Elder Rise van Thunder Bluff.",
  c = "Ik ben blij dat je vandaag de weg hierheen hebt gevonden, jonge $C. De tijd is gekomen voor een grote stap in een veel grotere wereld.$B$BIn elk kind van Cenarius zit de roep om de natuur te dienen. Dieren en planten zijn onze vrienden, en ook onze zorg. We kiezen ervoor ons leven te geven als bewaarders van het evenwicht. Voor hen, en ook voor onszelf. Je eerste stap in deze wereld: de wegen van de beer leren kennen. Je leert de kracht van lichaam en hart.$B$BMaak je klaar!",
  g = { {"roep", "call"}, {"beantwoorden", "to answer, to heed"}, {"laten weten", "let it be known"}, {"helpers", "assistants (helper)"}, {"staat bekend als", "is known as (bekendstaan)"}, {"geduldige", "patient (geduldig)"}, {"lesgeven", "to teach"}, {"dienen", "to serve"}, {"zorg", "care, charge"}, {"bewaarders", "preservers, keepers (bewaarder)"}, {"evenwicht", "balance"}, {"lichaam", "body"} },
},

[5927] = { en = "Heeding the Call", tier = 1,
  t = "De roep beantwoorden",
  d = "Pardon, vriend...$B$BIk heb gehoord dat Turak Runetotem met je wil praten. Hij heeft het laten weten. Het lijkt erop dat je training als druïde een nieuw leven krijgt. Hij gaat je zelf trainen. Turak is een van de helpers van de Arch Druid. Hij staat bekend als een wijze en geduldige druïde. Hij zal je goed lesgeven.$B$BJe vindt hem in Thunder Bluff, in de grote tent van de Cenarion Circle op de Elder Rise.",
  o = "Praat met Turak Runetotem op de Elder Rise van Thunder Bluff.",
  c = "Ik ben blij dat je vandaag de weg hierheen hebt gevonden, jonge $C. De tijd is gekomen voor een grote stap in een veel grotere wereld.$B$BIn elk kind van Cenarius zit de roep om de natuur te dienen. Dieren en planten zijn onze vrienden, en ook onze zorg. We kiezen ervoor ons leven te geven als bewaarders van het evenwicht. Voor hen, en ook voor onszelf. Je eerste stap in deze wereld: de wegen van de beer leren kennen. Je leert de kracht van lichaam en hart.$B$BMaak je klaar!",
