[5928] = { en = "Heeding the Call", tier = 1,
  t = "De roep beantwoorden",
  d = "Pardon, vriend...$B$BIk heb gehoord dat Turak Runetotem met je wil praten. Hij heeft het laten weten. Het lijkt erop dat je training als druïde een nieuw leven krijgt. Hij gaat je zelf trainen. Turak is een van de helpers van de Arch Druid. Hij staat bekend als een wijze en geduldige druïde. Hij zal je goed lesgeven.$B$BJe vindt hem in Thunder Bluff, in de grote tent van de Cenarion Circle op de Elder Rise.",
  o = "Praat met Turak Runetotem op de Elder Rise van Thunder Bluff.",
  c = "Ik ben blij dat je vandaag de weg hierheen hebt gevonden, jonge $C. De tijd is gekomen voor een grote stap in een veel grotere wereld.$B$BIn elk kind van Cenarius zit de roep om de natuur te dienen. Dieren en planten zijn onze vrienden, en ook onze zorg. We kiezen ervoor ons leven te geven als bewaarders van het evenwicht. Voor hen, en ook voor onszelf. Je eerste stap in deze wereld: de wegen van de beer leren kennen. Je leert de kracht van lichaam en hart.$B$BMaak je klaar!",
