[5930] = { en = "Great Bear Spirit", tier = 1,
  t = "Great Bear Spirit",
  d = "In het noordwesten van Moonglade woont een wijs en edel wezen. Wij noemen het de Great Bear Spirit. Voor alle druïden is het een leraar en gids. Het helpt hen de beer voor het eerst echt te begrijpen. Alle druïden zoeken ooit de wijsheid van de geest. Jij ook.$B$BGa nu naar de Great Bear Spirit en leer wat hij je leert. Als hij tevreden over je is, kom dan terug naar mij in Nighthaven. Dan zien we of je de lessen echt hebt begrepen.",
  o = "Zoek de Great Bear Spirit in het noordwesten van Moonglade. Leer wat hij je wil vertellen over de aard van de beer. Ga daarna terug naar Dendrite Starblaze in Nighthaven, Moonglade.",
  p = "Kom pas terug als de Great Bear Spirit je terugstuurt naar mij. Zonder zijn zegen kan je training niet verder.",
  c = "Dendrite maakt weer een onzichtbaar gebaar in de lucht boven zich als je dichterbij komt. Weer komt er een schijnsel van kracht over hem. Hij glimlacht een heel klein beetje.$B$B\"Ik voel wijsheid in je, jongeling. Die wijsheid er niet was toen we elkaar voor het eerst zagen. Je kijkt me aan met kracht en met een duidelijk doel. Maar dat doel is nog niet scherp. Je leert nu je kracht te richten. En je leert de aard van de beer in je werk te gebruiken.\"",
  e = "Zoek de Great Bear Spirit en leer wat hij je wil vertellen over de aard van de beer.",
  g = { {"edel", "noble"}, {"wezen", "being, creature"}, {"gids", "guide, mentor"}, {"wijsheid", "wisdom"}, {"tevreden", "satisfied"}, {"aard", "nature, character"}, {"zegen", "blessing"}, {"glimlacht", "smiles (glimlachen)"}, {"doel", "purpose, intent"}, {"scherp", "sharp, focused"}, {"richten", "to focus, to aim"} },
},

[5932] = { en = "Back to Thunder Bluff", tier = 1,
  t = "Terug naar Thunder Bluff",
  d = "De tijd is gekomen om afscheid te nemen, jongeling. Je gaat je lessen gebruiken, en daarom ga je terug naar wie je naar mij heeft gestuurd. Men denkt dat de tauren nog jong zijn in de wegen van Cenarius. Toch leeft Turak Runetotem met veel evenwicht in de natuur. Luister naar zijn opdrachten. Dan maak je snel je eerste lessen af als beschermer van het evenwicht.$B$BGa nu, jongeling. We zien elkaar weer.",
  o = "Ga terug naar Thunder Bluff en praat met Turak Runetotem op de Elder Rise.",
  c = "Welkom terug, $N. Ik voel het: je eerste ontmoeting met de Great Bear Spirit was net als bij alle druïden die het pad van de Klauw op gaan... een beetje verwarrend, maar heel sterk. Bij mij was het ook zo.$B$BDe Great Bear Spirit hoort al bij Azeroth zolang Azeroth in de hemel bestaat. Wij tauren luisteren goed naar zulke geesten. En we hebben allemaal voordeel van zijn doel. Nu is de tijd gekomen voor je eerste test van dit doel. Luister goed...",
  g = { {"afscheid nemen", "to say goodbye, to part ways"}, {"opdrachten", "instructions (opdracht)"}, {"maak af", "finish (afmaken)"}, {"ontmoeting", "meeting"}, {"verwarrend", "confusing, bewildering"}, {"hemel", "heavens, sky"}, {"bestaat", "exists (bestaan)"}, {"voordeel", "benefit"}, {"zulke", "such (zulk)"} },
},

[6002] = { en = "Body and Heart", tier = 1,
  t = "Lichaam en hart",
  d = "In de Barrens, ten westen van Taurajo, ligt een Moonkin Stone. Hij ligt vlak voor de grens met Mulgore. De moonkin zijn bijzondere beesten. Ze komen hier niet vandaan. Lunaclaw is de verdediger van de steen. Hij zal tegen je vechten als je Cenarion Lunardust op de steen gebruikt. In Lunaclaw zit een kracht. Die kracht moet jij gebruiken, als iemand van de Klauw.$B$BJe hebt het recht verdiend om deze Cenarion Lunardust te gebruiken, $N... Laat me nu zien dat je ook de kracht van lichaam en hart verdient die een druïde nodig heeft!",
  o = "Gebruik de Cenarion Lunardust op de Moonkin Stone tussen Mulgore en de Barrens om Lunaclaw op te roepen. Vecht dan tegen Lunaclaw en verdien de kracht van lichaam en hart die hij heeft.$B$BPraat met Turak Runetotem in Thunder Bluff als je klaar bent.",
  p = "Ga eerst de uitdaging aan die voor je ligt. Dan begrijp je de kracht van lichaam en de kracht van hart helemaal. Tot die tijd kan ik je niet verder helpen.",
  c = "Je hebt eindelijk je grote stap gezet in een veel grotere wereld, $N. Ik voel de les van de Great Bear Spirit in je. En ik voel dat je de kracht van Lunaclaw hebt gekregen.$B$BEr staat niets meer in je weg... Laat me je nu leren wat het betekent om een $C van de Klauw te zijn!",
  e = "Vecht tegen Lunaclaw en verdien de kracht van lichaam en hart die hij heeft.",
  o1 = "Vecht tegen Lunaclaw en verdien de kracht van lichaam en hart die hij heeft.",
  g = { {"grens", "border"}, {"bijzondere", "special (bijzonder)"}, {"beesten", "beasts (beest)"}, {"verdediger", "defender"}, {"recht", "right"}, {"verdiend", "earned (verdienen)"}, {"op te roepen", "to summon, to bring forth (oproepen)"}, {"uitdaging", "challenge"}, {"eindelijk", "finally"}, {"in je weg", "in your way"} },
},

[6126] = { en = "Lessons Anew", tier = 1,
  t = "Nieuwe lessen",
  d = "Je bent nu klaar om te leren over gif, en over de macht die wij druïden erover hebben, $N. Cenarius heeft ons een gave gegeven: met maar één toverspreuk kunnen we zelfs het ergste gif verwijderen. Neem deze gave niet licht op... Om zeker te zijn dat je deze les leert, ga je vergiftigingen eerst aanpakken zoals een gewoon mens dat zou doen.$B$BReis naar Moonglade en praat met Dendrite Starblaze. Hij wacht op je om je les te beginnen.",
  o = "Reis naar Moonglade en praat met Dendrite Starblaze in het dorp Nighthaven.",
  c = "Gegroet, jonge druïde. Ik ben blij dat je klaar bent en graag wilt leren over het genezen van gif.$B$BVroeger moesten de meeste druïden geplande proeven doen. Maar jouw werk wordt anders. In de Crossroads, in de Barrens, worden opeens veel dieren vergiftigd. Ze krijgen het daar niet onder controle. Iemand daar heeft Moonglade om hulp gevraagd. Daarom sturen we jou om hen te helpen. Dit is geen oefening. Het werk dat je gaat doen is echt. Denk daaraan.",
  g = { {"gif", "poison"}, {"macht", "power"}, {"gave", "gift"}, {"toverspreuk", "incantation, spell"}, {"verwijderen", "to remove, to purge"}, {"licht opnemen", "to take lightly"}, {"vergiftigingen", "poisonings (vergiftiging)"}, {"aanpakken", "to deal with, to tackle"}, {"genezen", "curing, to cure"}, {"geplande", "planned (gepland)"}, {"proeven", "trials (proef)"}, {"vergiftigd", "poisoned (vergiftigen)"}, {"oefening", "exercise"} },
},

[6127] = { en = "The Principal Source", tier = 1,
  t = "De belangrijkste bron",
  d = "Dreadmist Peak ligt ten noordwesten van de Crossroads. Daar begint het gif zich waarschijnlijk te verspreiden. Op de hoge, luchtige toppen liggen poelen met water. Die hebben invloed op het weer. Ik denk dat het water nu vervuild is door de Burning Blade. Zij aanbidden demonen.$B$BGebruik dit flesje om water te halen uit de poel op de hoogste top. Breng het volle flesje naar Tonga Runetotem in de Crossroads. Hij heeft ons om hulp gevraagd. Samen met hem ga je deze ziekte aanpakken.",
  o = "Gebruik de Empty Dreadmist Peak Sampler om water te halen uit een poel boven op de top.$B$BBreng de Filled Dreadmist Peak Sampler naar Tonga Runetotem in de Crossroads, Barrens.",
  p = "Jij bent degene die de Cenarion Circle in Moonglade heeft gestuurd, toch? Wat een geluk voor ons! We komen niet verder met het genezen van de zieke gazellen in het noorden van de Barrens. We zijn blij met alle hulp die we kunnen krijgen.$B$BHeb je het water bij je waar Dendrite Starblaze over sprak? Hij liet me weten dat je wat water zou halen, zodat we samen aan een geneesmiddel kunnen werken...",
  c = "Bij mijn voorouders, dit water is vies! Geen wonder dat de gazellen ziek zijn.$B$BIets vervuilt het water. Daardoor raakt de natuur in het noorden van de Barrens beschadigd. Overal ten noorden van de weg van oost naar west zijn zieke gazellen gezien. Dit water is waarschijnlijk de belangrijkste bron van de ziekte. Maar er is hier nog iets anders aan de hand.$B$BGeloof het of niet: dit water helpt ons een geneesmiddel te maken. Ik ga het water onderzoeken. Intussen heb ik een paar dingen nodig voor het geneesmiddel...",
  g = { {"bron", "source"}, {"waarschijnlijk", "probably"}, {"luchtige", "airy (luchtig)"}, {"toppen", "peaks (top)"}, {"poelen", "pools (poel)"}, {"invloed", "influence"}, {"vervuild", "polluted, tainted (vervuilen)"}, {"aanbidden", "worship (aanbidden)"}, {"ziekte", "sickness, malady"}, {"degene", "the one"}, {"gazellen", "gazelles (gazelle)"}, {"geneesmiddel", "cure, medicine"}, {"vies", "disgusting, dirty"}, {"beschadigd", "damaged (beschadigen)"}, {"aan de hand", "going on"} },
},

[6128] = { en = "Gathering the Cure", tier = 1,
  t = "Het geneesmiddel verzamelen",
  d = "Het water wordt de basis van de genezende zalf die ik voor de gazellen ga maken. Om te genezen heb ik wat earthroot nodig. Kruidenzoekers weten hoe ze die kunnen vinden. Ken jij dat vak niet? Dan moet je er een zoeken om ons te helpen.$B$BEn voor de kracht heb ik kodohoorns nodig. Kleine stukjes en splinters zijn niet genoeg. In het noorden van de Barrens lopen kodo's die jij aankunt. Versla er een paar, voor het grotere goed van het evenwicht, $N. En breng mij de hoorns.",
  o = "Breng 5 Earthroot en 5 Kodo Horns naar Tonga Runetotem in de Crossroads, zodat hij een genezende zalf kan maken.",
  p = "Heb je de ingrediënten die ik nodig heb voor de zalf? De gazellen worden niet vanzelf beter. We moeten dus niet treuzelen als we ze willen redden!",
  c = "Dit is goed, $N. Het is zelfs zo goed dat ik er genoeg doses zalf van kan maken. Genoeg om in elk geval een verschil te maken.$B$BEen middel tegen gif maken is soms heel moeilijk. Elk gif heeft vaak een heel bepaald tegengif nodig. Stel je voor dat je een gif kunt genezen wanneer je maar wilt! Zonder je zorgen te maken over wat er precies in het tegengif moet!$B$BNu ga ik hier aan het werk!",
  g = { {"genezende", "curative, healing (genezend)"}, {"zalf", "salve, ointment"}, {"kruidenzoekers", "herbalists (kruidenzoeker)"}, {"vak", "trade, skill"}, {"kodohoorns", "kodo horns (kodohoorn)"}, {"splinters", "fragments (splinter)"}, {"aankunt", "can handle (aankunnen)"}, {"versla", "defeat (verslaan)"}, {"vanzelf", "on their own"}, {"treuzelen", "to dawdle, to tarry"}, {"doses", "doses (dosis)"}, {"bepaald", "specific"}, {"tegengif", "antidote"}, {"stel je voor", "imagine (zich voorstellen)"} },
},

[6129] = { en = "Curing the Sick", tier = 1,
  t = "De zieken genezen",
  d = "Ik kon genoeg zalf maken voor tien keer genezen, $N. Ik ga samen met de leiders hier proberen meer zalf te maken. Intussen wil ik dat jij ons helpt om alvast te beginnen. Overal in het noorden van de Barrens zijn zieke gazellen. Gebruik de zalf op ze en genees hun ziekte.$B$BDendrite Starblaze in Moonglade wil je vast spreken als je klaar bent. Zeg de Cenarion Circle daar alsjeblieft dank namens ons... En ik wil jou ook zelf bedanken voor je hulp!",
  o = "Gebruik de Curative Animal Salve op 10 Sickly Gazelles in het noorden van de Barrens. Zo genees je ze. Er zijn Sickly Gazelles gezien ten noorden van de weg van oost naar west die door de Crossroads loopt.",
  p = "Heb je gedaan wat Tonga Runetotem in de Crossroads je vroeg? Pas dan is je werk klaar.",
  c = "Je hebt goed gezorgd voor de zieke gazellen van de Barrens. Ze zijn onschuldige slachtoffers van een groter kwaad en bederf dat zich over het hele land verspreidt. Jullie $R willen heel graag de wegen van Cenarius begrijpen. Net als je oudsten in Thunder Bluff laat jij zien dat de behoefte aan evenwicht sterker is dan kunstmatige grenzen tussen volken.$B$B$N, je hebt laten zien dat je een waardevolle vriend van de natuur en van de Circle bent. Neem dit als teken daarvan.",
  o1 = "Sickly Gazelle genezen",
  g = { {"leiders", "authorities, leaders (leider)"}, {"alvast", "already, ahead of time"}, {"genees", "cure (genezen)"}, {"namens", "on behalf of"}, {"onschuldige", "innocent, unwitting (onschuldig)"}, {"slachtoffers", "victims (slachtoffer)"}, {"kwaad", "evil, taint"}, {"bederf", "corruption, decay"}, {"oudsten", "elders (oudste)"}, {"behoefte", "need"}, {"kunstmatige", "artificial (kunstmatig)"}, {"volken", "peoples, races (volk)"}, {"waardevolle", "valuable (waardevol)"}, {"teken", "sign, symbol"} },
},

[6130] = { en = "Power over Poison", tier = 1,
  t = "Macht over gif",
  d = "Je weet nu wat het betekent om gif te genezen zonder hulp van de geesten. Je krijgt straks je nieuwe macht over gif. Denk dan aan wat anderen moeten doorstaan als ze vechten tegen vergiftigingen.$B$BGa nu terug naar Turak Runetotem in Thunder Bluff, $N. Hij heeft vast een heel belangrijke spreuk voor je, nu de leerling de les heeft begrepen die $ghem:haar; gegeven is.$B$BVaarwel, jonge druïde. We spreken elkaar weer.",
  o = "Ga terug naar Turak Runetotem op de Elder Rise, Thunder Bluff.",
  c = "Welkom terug. Ik heb je voortgang bij deze les gevolgd sinds je weg bent. Ik moet zeggen dat ik verrast was over wat er in de Crossroads gebeurt. Dit moet verder onderzocht worden. Zulk gif in de natuur brengt het evenwicht erg uit balans.$B$BJe bleef rustig en sterk onder druk. Daarom kan ik je niet beter belonen dan met blijvende macht over gif. Gebruik het goed, $N... gebruik het goed.",
  g = { {"doorstaan", "to endure"}, {"leerling", "student"}, {"vaarwel", "farewell"}, {"voortgang", "progress"}, {"verrast", "surprised"}, {"onderzocht", "investigated (onderzoeken)"}, {"uit balans", "out of balance"}, {"onder druk", "under pressure"}, {"belonen", "to reward"}, {"blijvende", "permanent, lasting (blijvend)"} },
},

[27] = { en = "A Lesson to Learn", tier = 1,
  t = "Een les om te leren",
  d = "$N, ik volg je voortgang met veel plezier. Je wordt echt een waardevolle beschermer van de natuur.$B$BDe tijd is gekomen om meer te leren over een van de dierlijke gedaanten waarin Cenarius ons laat veranderen. Deze gedaante geeft je macht en meesterschap over het water. Reis hiervoor naar het dorp Nighthaven in Moonglade. Praat daar met Dendrite Starblaze van de Cenarion Circle. Hij helpt je verder.",
  o = "Praat met Dendrite Starblaze in het dorp Nighthaven, Moonglade.",
  c = "Gegroet, jonge $C. De tijd is gekomen dat je onze watergedaante leert kennen. Met deze gedaante beweeg je vrij en zonder einde door het water. Je zult zien dat dit een nuttig hulpmiddel en een zegen is... Maar je moet hem eerst verdienen voordat je hem beheerst.$B$BJe krijgt twee proeven. De eerste test of je onder druk in het water kunt werken. De tweede test of je echt wilt begrijpen wat deze gedaante is.$B$BMaak je klaar, want de tijd van de proeven is nu gekomen.",
  g = { {"dierlijke", "animal (dierlijk)"}, {"gedaanten", "forms, aspects (gedaante)"}, {"veranderen", "to change, to shift"}, {"meesterschap", "mastery"}, {"watergedaante", "aquatic form"}, {"beweeg", "move (bewegen)"}, {"nuttig", "useful"}, {"hulpmiddel", "tool"}, {"beheerst", "masters (beheersen)"}, {"proeven", "trials (proef)"} },
},

[28] = { en = "Trial of the Lake", tier = 1,
  t = "Trial of the Lake",
  d = "Voor je eerste proef zoek je in de diepte van Lake Elune'ara naar een Shrine Bauble. Hij vergaat snel. Ga er dus zo snel mogelijk mee naar de Shrine of Remulos. Gebruik de bauble bij het heiligdom. Praat daarna met Tajarri daar. Zij is een van de meest vertrouwde wachters van Moonglade.$B$BJe hebt maar een beperkte tijd voor de taak. Misschien zoeken andere druïden ook naar baubles. Dan moet je tegen hen strijden. Snel denken en snel bewegen zijn heel belangrijk om te slagen.$B$BVeel succes, $N.",
  o = "Zoek een Shrine Bauble in Lake Elune'ara en breng hem naar de Shrine of Remulos in het noordwesten van Moonglade. Gebruik de Shrine Bauble daar.$B$BPraat daarna met Tajarri bij het heiligdom om de proef af te maken.",
  p = "Om de Trial of the Lake af te maken, moet je de Shrine Bauble binnen de grenzen van dit heiligdom gebruiken. Tot je dat doet, is je proef niet klaar. En dan kan hij mislukken.",
  c = "Zo zo. Het lijkt erop dat weer een druïde de Trial of the Lake heeft gehaald! Goed gedaan, mijn jonge vriend. Goed gedaan.$B$BZoals ik al zei, mijn naam is Tajarri. Het is mijn taak en mijn eer om wachter te zijn van Moonglade, en vooral van dit heiligdom. Keeper Remulos leidt de Cenarion Circle in het beschermen van natuur en evenwicht. Zijn heiligdom is een blijvend eerbetoon daaraan. Door de bauble hier te gebruiken, toon je hoe belangrijk deze plek is voor de Circle.",
  e = "Maak de Trial of the Lake af.",
  g = { {"diepte", "depths"}, {"vergaat", "decays (vergaan)"}, {"heiligdom", "shrine"}, {"vertrouwde", "trusted (vertrouwd)"}, {"wachters", "wardens (wachter)"}, {"beperkte", "limited (beperkt)"}, {"strijden", "to compete, to fight"}, {"slagen", "to succeed"}, {"mislukken", "to fail"}, {"eer", "honour, privilege"}, {"leidt", "guides, leads (leiden)"}, {"eerbetoon", "tribute"}, {"toon", "show (tonen)"} },
},

[30] = { en = "Trial of the Sea Lion", tier = 1,
  t = "Trial of the Sea Lion",
  d = "Voor de tweede proef heb je de twee helften van de Pendant of the Sea Lion nodig. De ene helft krijgt kracht van de behendigheid van de zeeleeuw, die door het water glijdt. De andere helft krijgt kracht van het geweldige uithoudingsvermogen van de zeeleeuw. Druïden gebruiken deze twee eigenschappen even veel. Zo worden ze één met hun watergedaante.$B$BPraat met de bewoners van Moonglade. Zij weten waar de delen kunnen liggen. Breng ze allebei hier en voeg ze samen. Breng de hanger daarna naar Dendrite Starblaze.",
  o = "Zoek de Half Pendant of Aquatic Agility en de Half Pendant of Aquatic Endurance. Praat met de bewoners van Moonglade voor aanwijzingen over waar deze voorwerpen liggen.$B$BMaak de Pendant of the Sea Lion van de twee helften. Je moet daarvoor dicht bij de Shrine of Remulos zijn.$B$BBreng de hele hanger naar Dendrite Starblaze in het dorp Nighthaven, Moonglade.",
  p = "Heb je je hanger gemaakt, zodat ik hem kan bekijken, $N? Heb je hulp nodig om de delen te vinden? Vraag dan de mensen hier om informatie. Zo vind je wat je zoekt. En je hebt meteen een reden om deze prachtige, heilige open plek te verkennen.",
  c = "Je hebt de Trial of the Sea Lion gehaald, $n. Gefeliciteerd.$B$BElke taak om de hanger te krijgen laat zien dat je behendigheid en uithoudingsvermogen allebei nodig hebt. Alleen dan ben je in harmonie met wat je onder water wilt doen. Het een kan niet zonder het ander. En allebei lukken ze niet zonder dat je de gedaante van de zeeleeuw wilt omarmen.$b$bOnthoud deze lessen goed. Vertrouw erop als je je watergedaante hebt gekregen.",
  g = { {"helften", "halves (helft)"}, {"behendigheid", "agility"}, {"zeeleeuw", "sea lion"}, {"glijdt", "glides (glijden)"}, {"uithoudingsvermogen", "endurance"}, {"eigenschappen", "traits (eigenschap)"}, {"bewoners", "residents (bewoner)"}, {"voeg samen", "join together (samenvoegen)"}, {"hanger", "pendant"}, {"aanwijzingen", "clues (aanwijzing)"}, {"prachtige", "wondrous, beautiful (prachtig)"}, {"open plek", "glade, clearing"}, {"verkennen", "to explore"}, {"gefeliciteerd", "congratulations"}, {"vertrouw erop", "count on it (vertrouwen op)"} },
},

[31] = { en = "Aquatic Form", tier = 1,
  t = "Watergedaante",
  d = "Je hebt de lessen gehad die alle jonge druïden krijgen voordat ze een watergedaante kunnen aannemen. Ga nu terug naar je leraar, Turak Runetotem, in Thunder Bluff. Laat hem je hanger zien en bewijs dat je klaar bent om te leren wat hij je kan leren. Hij maakt je training af. Dan word je één met het water.$B$BTot ziens, jonge druïde. We spreken elkaar weer.",
  o = "Ga terug naar Thunder Bluff en laat Turak Runetotem de Pendant of the Sea Lion zien.",
  p = "Je terugkomst in Thunder Bluff is al aangekondigd. Toch heb ik bewijs nodig van de lessen die je in Moonglade hebt geleerd. Pas dan leer ik je je watergedaante.$B$BHeb je de Pendant of the Sea Lion?",
  c = "Heel indrukwekkend, $N. Je voorouders zouden blij zijn met je voortgang! Je bent klaar om je watergedaante te leren. Het is een eer voor mij om je die te leren.$B$BOok krijg je dit voorwerp, als erkenning voor wat je in de twee proeven hebt gedaan. Ik hoop dat het een mooie aanvulling is op je uitrusting als beschermer van de natuur en bewaarder van het evenwicht.",
  g = { {"aannemen", "to adopt, to take on"}, {"bewijs", "prove (bewijzen); proof"}, {"terugkomst", "return"}, {"aangekondigd", "announced, heralded (aankondigen)"}, {"indrukwekkend", "impressive"}, {"voorwerp", "item, object"}, {"erkenning", "recognition"}, {"aanvulling", "addition"}, {"uitrusting", "gear, equipment"} },
},

})

